"""📚 Knowledge base (Admin, read-only): browse every article, see how often it is cited and rated."""
from collections import Counter

import pandas as pd
import streamlit as st

from app import backend, state, ui
from src.taxonomy import CATEGORIES, SERVICES

state.require_role("admin")
ui.page_header("📚", "Knowledge base",
               "Read-only. Articles are generated by us (Prompts/KB_GENERATION_PROMPT.md).")

ACCESS_COLOR = {"public": "green", "internal": "orange"}
ALL_SUBCATEGORIES = [s for subs in CATEGORIES.values() for s in subs]


def access_badge(level: str) -> str:
    return ui.badge(level, ACCESS_COLOR.get(level, "gray"))


# ── Load everything the admin may see (unfiltered: used for detail view + related links) ──
try:
    all_articles = backend.list_kb({}, role="admin")
except Exception as e:  # noqa: BLE001 - friendly message, never a traceback
    ui.show_error(e)
    st.stop()
by_id = {a["kb_id"]: a for a in all_articles}

# ── Times cited (audit) and useful / incorrect counts (feedback) ───────────
audit_error = feedback_error = None
cited: Counter = Counter()
n_analyses = 0
try:
    analyses = backend.get_audit({})
    n_analyses = len(analyses)
    for r in analyses:
        ids = {a.get("kb_id") for a in ((r.get("kb") or {}).get("articles") or [])}
        cited.update(i for i in ids if i)
except Exception as e:  # noqa: BLE001
    audit_error = f"{type(e).__name__}"

useful: Counter = Counter()
incorrect: Counter = Counter()
try:
    for f in backend.get_feedback():
        if f.get("target_type") != "kb_article":
            continue
        if f.get("verdict") == "useful":
            useful[f.get("target_id")] += 1
        elif f.get("verdict") == "incorrect":
            incorrect[f.get("target_id")] += 1
except Exception as e:  # noqa: BLE001
    feedback_error = f"{type(e).__name__}"


# ── Filters ─────────────────────────────────────────────────────────────────
def _sub_options() -> list[str]:
    chosen = st.session_state.get("kb_f_category") or []
    return [s for c in chosen for s in CATEGORIES[c]] if chosen else ALL_SUBCATEGORIES


_subs = _sub_options()
if st.session_state.get("kb_f_subcategory"):
    st.session_state["kb_f_subcategory"] = [s for s in st.session_state["kb_f_subcategory"] if s in _subs]

access_levels = sorted({a.get("access_level", "public") for a in all_articles})

with st.container(border=True):
    st.text_input("Search", key="kb_f_text", placeholder="Any word in the article: title, symptom, error, step…")
    c1, c2, c3, c4 = st.columns(4)
    c1.multiselect("Category", list(CATEGORIES), key="kb_f_category", placeholder="Any")
    c2.multiselect("Subcategory", _subs, key="kb_f_subcategory", placeholder="Any")
    c3.multiselect("Access level", access_levels, key="kb_f_access", placeholder="Any")
    c4.multiselect("Service", list(SERVICES), key="kb_f_service", placeholder="Any")

filters = {
    "category": st.session_state.get("kb_f_category") or [],
    "subcategory": st.session_state.get("kb_f_subcategory") or [],
    "access_level": st.session_state.get("kb_f_access") or [],
    "service": st.session_state.get("kb_f_service") or [],
    "text": (st.session_state.get("kb_f_text") or "").strip(),
}
try:
    articles = backend.list_kb(filters, role="admin")
except Exception as e:  # noqa: BLE001
    ui.show_error(e)
    st.stop()

# ── Selection state: "kb_selected" is the single source of truth ────────────
st.session_state.setdefault("kb_selected", None)
st.session_state.setdefault("kb_table_v", 0)


def _select(kb_id: str) -> None:
    """Related-article button: switch the article and reset the table highlight."""
    st.session_state["kb_selected"] = kb_id
    st.session_state["kb_table_v"] += 1


def _on_table_select() -> None:
    rows = st.session_state[f"kb_table_{st.session_state['kb_table_v']}"].selection.rows
    ids = st.session_state.get("kb_table_ids") or []
    if rows and rows[0] < len(ids):
        st.session_state["kb_selected"] = ids[rows[0]]


def _on_pick() -> None:
    st.session_state["kb_table_v"] += 1


# ── List ────────────────────────────────────────────────────────────────────
if not articles:
    ui.empty_state("No articles match these filters — clear a filter or change the search words.")
else:
    st.markdown(f"**{len(articles)} of {len(all_articles)} articles** shown. Select a row to read it.")
    rows = [{
        "kb_id": a["kb_id"],
        "title": a["title"],
        "category": f"{a['category']} › {a['subcategory']}",
        "access": a.get("access_level", "public"),
        "cited": None if audit_error else cited.get(a["kb_id"], 0),
        "useful": None if feedback_error else useful.get(a["kb_id"], 0),
        "incorrect": None if feedback_error else incorrect.get(a["kb_id"], 0),
    } for a in articles]
    st.session_state["kb_table_ids"] = [r["kb_id"] for r in rows]
    st.dataframe(
        pd.DataFrame(rows),
        key=f"kb_table_{st.session_state['kb_table_v']}",
        hide_index=True,
        width="stretch",
        on_select=_on_table_select,
        selection_mode="single-row",
        column_config={
            "kb_id": st.column_config.TextColumn("ID", width="small"),
            "title": st.column_config.TextColumn("Title", width="large"),
            "category": st.column_config.TextColumn("Category › Subcategory", width="medium"),
            "access": st.column_config.TextColumn("Access", width="small",
                                                  help="public = employees can see it; internal = support only"),
            "cited": st.column_config.NumberColumn("Times cited", width="small",
                                                   help="Stored analyses that listed this article"),
            "useful": st.column_config.NumberColumn("Useful", width="small"),
            "incorrect": st.column_config.NumberColumn("Incorrect", width="small"),
        },
    )
    notes = [f"Times cited counts {n_analyses} stored analyses." if not audit_error
             else f"Times cited isn't available: the audit store could not be read ({audit_error})."]
    notes.append("Useful / incorrect come from feedback on KB articles." if not feedback_error
                 else f"Feedback counts aren't available: feedback could not be read ({feedback_error}).")
    st.caption(" ".join(notes))

st.selectbox("Article", list(by_id), key="kb_selected", on_change=_on_pick,
             format_func=lambda i: f"{i} — {by_id[i]['title']}" if i in by_id else i,
             placeholder="Pick an article, or select a row above")

# ── Detail ──────────────────────────────────────────────────────────────────
a = by_id.get(st.session_state.get("kb_selected"))
if a is None:
    st.caption("No article selected.")
    st.stop()

kb_id = a["kb_id"]
with st.container(border=True):
    st.markdown(f"#### {kb_id} · {a['title']}")
    st.markdown(" ".join([
        access_badge(a.get("access_level", "public")),
        ui.badge(f"{a['category']} › {a['subcategory']}", "blue"),
        *(ui.badge(s, "gray") for s in a.get("services", [])),
        *(ui.badge(t, "violet") for t in a.get("symptom_types", [])),
    ]))
    m1, m2, m3 = st.columns(3)
    m1.metric("Times cited", "—" if audit_error else cited.get(kb_id, 0))
    m2.metric("Useful", "—" if feedback_error else useful.get(kb_id, 0))
    m3.metric("Incorrect", "—" if feedback_error else incorrect.get(kb_id, 0))

    left, right = st.columns(2)
    with left:
        st.markdown("**Symptoms**")
        st.markdown("\n".join(f"- {s}" for s in a.get("symptoms", [])) or "—")
    with right:
        st.markdown("**Error messages**")
        errs = a.get("error_messages", [])
        st.markdown("\n".join(f"- `{e}`" for e in errs) if errs else "None listed.")
    st.markdown("**Cause**")
    st.markdown(a.get("cause") or "—")

steps = a.get("steps", [])
self_steps = [s for s in steps if s["type"] == "self"]
support_steps = [s for s in steps if s["type"] == "support"]

with st.container(border=True):
    st.markdown("**Self-help steps** (the employee can do these)")
    if self_steps:
        for s in self_steps:
            st.markdown(f"`{s['id']}` {s['text']}")
    else:
        st.caption("None.")
    st.markdown("**Support steps** (for the support team)")
    if support_steps:
        for s in support_steps:
            expected = f"  \n  *Expected:* {s['expected']}" if s.get("expected") else ""
            st.markdown(f"`{s['id']}` {s.get('do', s['text'])}{expected}")
    else:
        st.caption("None.")
    st.caption("Step IDs are the same IDs the recommended fix cites as its sources.")

with st.container(border=True):
    st.markdown("**Verify**")
    st.markdown(a.get("verify") or "—")
    e1, e2 = st.columns([1, 3])
    e1.markdown(f"**Escalate to**  \n{a.get('escalate_to') or '—'}")
    e2.markdown(f"**Escalate when**  \n{a.get('escalate_when') or '—'}")

related = a.get("related_articles") or []
with st.container(border=True):
    st.markdown("**Related articles**")
    if not related:
        st.caption("None listed.")
    else:
        cols = st.columns(min(len(related), 4))
        for i, rid in enumerate(related):
            target = by_id.get(rid)
            label = f"{rid} — {target['title']}" if target else f"{rid} (not found)"
            cols[i % len(cols)].button(label, key=f"kb_rel_{kb_id}_{rid}", on_click=_select, args=(rid,),
                                       disabled=target is None, width="stretch")

if a.get("keywords"):
    with st.expander("Search keywords"):
        st.markdown(" ".join(ui.badge(k, "gray") for k in a["keywords"]))
